<script>

/* =========================
   NAVIGATION
========================= */

const viewNames = {
    overview:"Overview",
    public:"Public Schedule",
    roster:"My Roster",
    generation:"Generate Schedule",
    draft:"Drafts",
    conflicts:"Conflicts",
    command:"Command Center"
};


function navigate(viewId, button){

    document
        .querySelectorAll(".view")
        .forEach(view=>{
            view.classList.remove("active");
        });

    document
        .getElementById(viewId)
        .classList.add("active");


    document
        .querySelectorAll(".nav-item")
        .forEach(item=>{
            item.classList.remove("active");
        });


    if(button){
        button.classList.add("active");
    }
    else{

        const nav =
            document.querySelector(
                `.nav-item[data-view="${viewId}"]`
            );

        if(nav){
            nav.classList.add("active");
        }
    }


    document
        .getElementById("breadcrumb")
        .innerText =
        viewNames[viewId];
}


/* =========================
   ROLE SWITCHING
========================= */

function changeRole(){

    const role =
        document
            .getElementById("roleSelect")
            .value;


    if(role==="public"){
        navigate("public");
    }

    else if(role==="captain"){
        navigate("roster");
    }

    else if(role==="rep"){
        navigate("overview");
    }

    else if(role==="head"){
        navigate("command");
    }
}


/* =========================
   PLAYER MODAL
========================= */

function openPlayerModal(){

    document
        .getElementById("duplicateError")
        .classList.remove("show");

    document
        .getElementById("playerModal")
        .classList.add("show");
}


function closePlayerModal(){

    document
        .getElementById("playerModal")
        .classList.remove("show");
}


function addPlayer(){

    const id =
        document
            .getElementById("studentId")
            .value
            .trim();

    const name =
        document
            .getElementById("studentName")
            .value
            .trim();


    if(!id || !name){

        showToast(
            "Please enter both the Student ID and name."
        );

        return;
    }


    if(id==="202401"){

        document
            .getElementById("duplicateError")
            .classList.add("show");

        return;
    }


    closePlayerModal();

    showToast(
        name + " was successfully added to the roster."
    );

}


/* =========================
   MATCH
========================= */

function openMatch(){

    document
        .getElementById("matchModal")
        .classList.add("show");
}


function closeMatch(){

    document
        .getElementById("matchModal")
        .classList.remove("show");
}


/* =========================
   SEARCH
========================= */

function filterSchedule(){

    const query =
        document
            .getElementById("searchInput")
            .value
            .toLowerCase();


    const sport =
        document
            .getElementById("sportFilter")
            .value;


    document
        .querySelectorAll("#scheduleBody tr")
        .forEach(row=>{

            const text =
                row
                    .innerText
                    .toLowerCase();

            const matchesSearch =
                text.includes(query);

            const matchesSport =
                !sport ||
                row.innerText.includes(sport);

            row.style.display =
                matchesSearch && matchesSport
                    ? ""
                    : "none";
        });
}


/* =========================
   GENERATION
========================= */

function startGeneration(){

    navigate("generation");


    const bar =
        document.getElementById("progressBar");

    const text =
        document.getElementById("generationText");

    const queued =
        document.getElementById("queuedStep");

    const running =
        document.getElementById("runningStep");

    const completed =
        document.getElementById("completedStep");


    queued.className="step current";
    running.className="step";
    completed.className="step";

    bar.style.width="8%";

    text.innerText =
        "Schedule request queued. Preparing solver...";


    setTimeout(()=>{

        queued.className="step done";
        running.className="step current";

        bar.style.width="55%";

        text.innerText =
            "Solver is running. Checking venues and player conflicts...";

    },1500);


    setTimeout(()=>{

        running.className="step done";
        completed.className="step current";

        bar.style.width="100%";

        text.innerText =
            "Generation complete. Draft Version 3 is ready for review.";

        showToast(
            "Schedule generated successfully."
        );


        setTimeout(()=>{

            navigate("draft");

        },1200);

    },4000);
}


/* =========================
   PUBLISH
========================= */

function publishDraft(){

    showToast(
        "Draft published. Public schedule has been updated."
    );


    setTimeout(()=>{

        navigate("public");

        document
            .getElementById("roleSelect")
            .value="public";

    },1200);
}


/* =========================
   CONFLICT
========================= */

function resolveConflict(button){

    button.innerText="Resolved";

    button.classList.remove("btn-secondary");

    button.classList.add("btn-success");

    button.disabled=true;

    showToast(
        "Conflict resolved. Schedule can be updated."
    );
}


/* =========================
   EXPORT
========================= */

function exportCalendar(){

    showToast(
        "iCal calendar export prepared."
    );
}


/* =========================
   TOAST
========================= */

function showToast(message){

    const toast =
        document.getElementById("toast");

    toast.innerText=message;

    toast.classList.add("show");


    setTimeout(()=>{

        toast.classList.remove("show");

    },3000);
}

</script>

</body>
</html>

